from __future__ import annotations
from abc_creative_gold_v5_101_200_support import make_spec, register_craft
FACTS={
"Airport":"Facility coordinates aircraft movement, passengers, cargo, security, runways, taxiways, gates, and ground services.",
"Biplane":"Fixed-wing airplane with two main wings stacked vertically; struts/bracing are common in classic designs.",
"Cockpit":"Crew control area contains flight controls, instruments, displays, and communications; passengers do not enter during normal operations.",
"Departure Board":"Display lists flights, times, gates, and status; operational changes can update after a passenger first checks it.",
"Engine":"Aircraft engine provides thrust or shaft power; turbine, piston, electric, and other designs work differently.",
"Flight Deck":"Another term for the aircraft cockpit/crew control area; it is a restricted operational workspace.",
"Gate":"Airport gate is a passenger boarding/arrival area assigned to a flight; it is not the runway or aircraft parking stand itself.",
"Helicopter":"Rotorcraft uses rotating wings for lift and can hover; rotor areas are dangerous and approached only under trained procedures.",
"Instrument Panel":"Panel/display area presents flight, engine, navigation, and system information to pilots; exact instruments vary by aircraft.",
"Jetway":"Enclosed passenger boarding bridge connects terminal gate to an aircraft door when positioned and secured by trained staff.",
"Kerosene Tank":"Fuel tank stores aviation turbine fuel such as kerosene-based jet fuel; fueling areas are restricted fire-safety zones.",
"Landing Gear":"Wheels, struts, or other gear support an aircraft on ground and absorb landing loads; many aircraft retract gear in flight.",
"Marshaller":"Trained ground worker uses standardized visual signals to guide aircraft positioning; passengers should not copy signals near operating aircraft.",
"Navigation Light":"Aircraft position lights help others determine orientation, commonly red left, green right, white aft under standard conventions.",
"Oxygen Mask":"Emergency aviation mask supplies supplemental oxygen during cabin-pressure problems; passengers follow crew instructions when directed.",
"Propeller":"Rotating blades accelerate air to create thrust; propellers are severe hazards and require complete clearance when operating.",
"Queue Lane":"Marked airport line organizes passengers for check-in, security, or boarding; it is a flow-control feature.",
"Runway":"Prepared surface used for aircraft takeoff and landing; it is a tightly controlled area, never a pedestrian viewing path.",
"Seatbelt":"Aircraft restraint holds a passenger to the seat during turbulence, takeoff, landing, or whenever instructed; buckle stays low and snug.",
"Tail":"Rear aircraft structure includes stabilizing surfaces such as vertical and horizontal stabilizers in many designs.",
"Uniform":"Crew or ground-service clothing identifies role and organization; uniform itself does not grant passengers operational authority.",
"Visor":"Cockpit/passenger sun visor reduces glare; it is not the same as a head-up display or flight instrument.",
"Wing":"Airfoil surface produces lift through airflow and pressure effects; wings also carry structure, fuel, or controls depending design.",
"X-wing Model":"Model of the fictional X-wing starfighter; it is a science-fiction comparison object, not a real certified aircraft type.",
"Yellow Taxiway Sign":"Yellow-background airport signs commonly give taxiway direction/destination information; exact meaning comes from text, arrows, and local standards.",
"Zero-gravity Plane":"Aircraft flying parabolic arcs creates brief microgravity as occupants and cabin follow free-fall together; gravity is not switched off.",
"Airplane":"Powered fixed-wing aircraft uses forward motion through air to generate wing lift; propulsion and configuration vary.",
"Boarding Pass":"Travel document/token links a passenger to a flight and often seat/gate data; gate/time still need current checks.",
"Elevator Trim":"Trim system reduces sustained pitch-control force by adjusting a trim tab, stabilizer, or control command depending aircraft.",
"Fuselage":"Main aircraft body houses crew, passengers, cargo, or systems and connects wings/tail in conventional layouts.",
"Glider":"Aircraft designed for unpowered soaring after launch or tow; it trades altitude and rising air for continued flight.",
"Inflatable Slide":"Emergency evacuation slide deploys from some aircraft doors; crew procedures govern use and accidental deployment is hazardous.",
"Jet":"Aircraft or engine using jet propulsion accelerates a high-speed exhaust stream; jet describes propulsion more than body shape.",
"Kite":"Tethered flying object held by aerodynamic forces and a line; fly far from airports, storms, roads, and power lines.",
"Luggage Cart":"Ground vehicle/cart moves baggage around airport service areas; ramp traffic is controlled and not passenger play space.",
"Monoplane":"Fixed-wing aircraft with one main wing plane, unlike a biplane's two stacked wing planes.",
"Overhead Bin":"Cabin storage compartment holds approved carry-on items; doors must latch and weight/size limits prevent falling baggage.",
"Passenger Plane":"Aircraft configured primarily to carry passengers; seating, range, propulsion, and size vary widely.",
"Radar":"System transmits radio waves and analyzes returns to detect range, direction, weather, or traffic information depending type.",
"Ultralight":"Very light aircraft category whose legal definition, training, licensing, and operating limits vary by country.",
"Vertical Stabilizer":"Vertical tail surface provides directional stability; a rudder is commonly hinged to it for yaw control.",
"X-ray Scanner":"Airport security imaging system uses controlled radiation to inspect baggage/items; trained staff operate it under safety procedures.",
"Cargo Plane":"Aircraft configured mainly to carry freight; loading balance and restraint are critical to safe flight.",
"Drone":"Uncrewed aircraft can be remotely piloted or automated; operation must follow local airspace, privacy, and safety rules.",
"Hangar":"Large building shelters aircraft for storage or maintenance; active maintenance areas are restricted workspaces.",
"Nose Wheel":"Forward landing-gear wheel(s) support and often steer a tricycle-gear aircraft on the ground.",
"Quadcopter":"Uncrewed rotorcraft with four rotors; changing relative rotor speeds controls lift and attitude.",
"Turboprop":"Gas-turbine engine drives a propeller through a gearbox; much of the thrust comes from the propeller.",
"Windsock":"Fabric cone shows approximate wind direction and gives a rough visual indication of wind strength; it is not a precision anemometer.",
"Yoke":"Wheel/column-style flight control used in some airplanes to command pitch/roll; many aircraft use sticks or sidesticks instead.",
"Zeppelin":"Rigid airship uses a structural framework and lifting gas for buoyancy; it is lighter-than-air aviation.",
"Seaplane":"Fixed-wing aircraft designed to take off and land on water using floats or a boat-like hull.",
}
ACTIONS={
"Kerosene Tank":"Point only; say restricted fuel area—no fueling mime.","Propeller":"Point only; make no spinning-arm gesture near people.","Runway":"Draw two parallel lines in air; no running/takeoff imitation.","X-ray Scanner":"Point only; trained security staff operate the real scanner.","Inflatable Slide":"Point only; no sliding/jumping mime.","Oxygen Mask":"Point to the mask picture; follow-crew cue, no bag-over-face play.","Drone":"Air-trace a small aircraft; no real indoor flight.","Quadcopter":"Trace four rotor circles with one finger; no real indoor flight.","Helicopter":"Point; slowly circle one finger above, never approach rotors.","Marshaller":"Point to the worker; no signaling near real aircraft.","Kite":"Trace a diamond; name distance from airports/power lines.","Luggage Cart":"Point only; ramp vehicles are work equipment.","Yoke":"Hold an imaginary control lightly; do not claim every plane has one."}
